const assert = require('node:assert/strict');
const fs = require('node:fs');
const {execFileSync} = require('node:child_process');
const espree = require('espree');
const name = 'scripts/inspect_eslint.mjs';
const before = execFileSync('git', ['show', 'ef057111b09f0b081e1c9c1dd61678bb29040a07:' + name], {encoding:'utf8'});
const after = fs.readFileSync(name, 'utf8');
const options = {ecmaVersion:'latest', sourceType:'module'};
const strip = (key, value) => ['start','end','range','loc'].includes(key) ? undefined : value;
assert.equal(JSON.stringify(espree.parse(before, options), strip), JSON.stringify(espree.parse(after, options), strip));
assert.equal(JSON.stringify(espree.tokenize(before, options), strip), JSON.stringify(espree.tokenize(after, options), strip));
console.log(name + ': complete JavaScript AST and token equality PASS (source positions excluded)');
